--- 获取当前等级和当前等级下的经验
---@return number 当前等级
---@return number 最大等级
---@return number 当前等级下的经验
---@return number 当前等级最大经验
function ActivityFashionPassComponent:GetLevelAndExp()
    local maxLevel = checkNumber(self:GetParamVo(1).num)
    local expEveryLevel = checkNumber(self:GetParamVo(2).num)

    -- 总经验值
    local curTotalExp = self.homeDojo.exp

    -- 当前等级
    local curLevel = math.floor(curTotalExp / expEveryLevel) + 1
    -- 当前等级下的经验
    local curExp = curTotalExp - (curLevel - 1) * expEveryLevel

    return curLevel, maxLevel, curExp, expEveryLevel
end

--- 是否已达最大等级
function ActivityFashionPassComponent:IsMaxLevel()
    local maxLevel = checkNumber(self:GetParamVo(1).num)
    local expEveryLevel = checkNumber(self:GetParamVo(2).num)

    -- 总经验值
    local curTotalExp = self.homeDojo.exp

    -- 当前等级
    local curLevel = math.floor(curTotalExp / expEveryLevel) + 1

    return curLevel >= maxLevel
end

--- 可以购买的等级数
function ActivityFashionPassComponent:CanBuyLevelNumMax()
    local maxLevel = checkNumber(self:GetParamVo(1).num)
    local expEveryLevel = checkNumber(self:GetParamVo(2).num)

    -- 总经验值
    local curTotalExp = self.homeDojo.exp

    -- 当前等级
    local curLevel = math.floor(curTotalExp / expEveryLevel) + 1

    return maxLevel - curLevel
end

