--- 获取指定等级范围内的奖励列表
---@param startLevel integer
---@param endedLevel integer
---@return table[] @ { goodsId : integer, goodsNum : integer }
function ActivityFashionPassComponent:GetLevelRewardDataList(startLevel, endedLevel)
    local scheduleId = self.activityContentId
    local baseRewardVos = self:GetBaseRewardVosByScheduleId(scheduleId)
    local advanceRewardVos = self:GetAdvanceRewardVosByScheduleId(scheduleId)

    local rewardsMap = {}
    for i, vo in ipairs(baseRewardVos) do
        if vo.level >= startLevel and vo.level <= endedLevel then
            for j, reward in ipairs(vo.rewards) do
                rewardsMap[reward.goodsId] = (rewardsMap[reward.goodsId] or 0) + reward.goodsNum
            end
        end
    end

    local hasPassCard = self:HasBoughtPassCard()
    if hasPassCard then
        for i, vo in ipairs(advanceRewardVos) do
            if vo.level >= startLevel and vo.level <= endedLevel then
                for j, reward in ipairs(vo.rewards) do
                    rewardsMap[reward.goodsId] = (rewardsMap[reward.goodsId] or 0) + reward.goodsNum
                end
            end
        end
    end
    
    ---@type table[] @ { goodsId : integer, goodsNum : integer }
    local rewardsList = {}
    for k, v in pairs(rewardsMap) do
        table.insert(rewardsList, {goodsId = k, goodsNum = v})
    end
    
    return rewardsList
end

--- 获取pass卡界面奖励列表的cellData
function ActivityFashionPassComponent:GetRewardCellDataList()
    local scheduleId = self.activityContentId
    local baseRewardVos = self:GetBaseRewardVosByScheduleId(scheduleId)
    local advanceRewardVos = self:GetAdvanceRewardVosByScheduleId(scheduleId)

    table.inPlaceBubbleSort(baseRewardVos, function(a, b)
        return a.level < b.level
    end)

    table.inPlaceBubbleSort(advanceRewardVos, function(a, b)
        return a.level < b.level
    end)

    local curLevel, maxLevel = self:GetLevelAndExp()
    
    local cellDataList = {}
    for i = 1, maxLevel, 1 do
        local baseRewardVo = baseRewardVos[i]
        local advanceRewardVo = advanceRewardVos[i]
        local baseRewardHasDrawn = table.isContain(self.homeDojo.drawnLevelRewards, baseRewardVo.id)
        local advanceRewardHasDrawn = table.isContain(self.homeDojo.drawnLevelRewards, advanceRewardVo.id)
        local cellData = {
            lastSpan = false,   -- 不是空占位
            level = i,
            unlock = i <= curLevel,
            baseRewardHasDrawn = baseRewardHasDrawn,
            advanceRewardHasDrawn = advanceRewardHasDrawn,
            baseRewardVo = baseRewardVo,
            advanceRewardVo = advanceRewardVo,
        }
        table.insert(cellDataList, cellData)
    end

    table.insert(cellDataList, {lastSpan = true})   -- 空占位

    return cellDataList
end

--- 获取指定等级的商品id
---@param level any
function ActivityFashionPassComponent:GetLevelProduceIdByLevel(level)
    local scheduleId = self.activityContentId
    local baseRewardVos = self:GetBaseRewardVosByScheduleId(scheduleId)
    local advanceRewardVos = self:GetAdvanceRewardVosByScheduleId(scheduleId)

    local baseProductId = 0
    for i, baseRewardVo in ipairs(baseRewardVos) do
        if baseRewardVo.level == level then
            baseProductId = baseRewardVo.id
            break
        end
    end

    local advanceProductId = 0
    for i, advanceRewardVo in ipairs(advanceRewardVos) do
        if advanceRewardVo.level == level then
            advanceProductId = advanceRewardVo.id
            break
        end
    end

    return baseProductId, advanceProductId
end

