---@param callback any
function ActivityFashionPassComponent:RequestDrawLevelReward(productId, callback)
    -- table.insert(self.homeDojo.drawnLevelRewards, productId)
    
    -- if callback then
    --     callback({})
    -- end
    -- do return end

    productId = checkNumber(productId)
    if productId == -1 then
        -- 一键领取
        productId = 0
    end
    GameUtils.Request(Interfaces.ActivityFashionPassDrawLevelRewards, {rewardId = productId, activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = checkTable(jsonData.rewards)
        self.homeDojo.drawnLevelRewards = checkTable(jsonData.drawnRewards)

        GoodsUtils.DrawRewards(rewards, true)

        if callback then
            callback(rewards)
        end
    end)
end

