--- 请求购买等级
function ActivityFashionPassComponent:RequestBuyLevel(num, callback)
    -- self.homeDojo.exp = self.homeDojo.exp + num * 100
    -- if self:IsMaxLevel() then
    --     self.homeDojo.dailyExpStatus = 2
    -- end
    -- if callback then
    --     callback(num * 100)
    -- end
    -- do return end

    GameUtils.Request(Interfaces.ActivityFashionPassBuyLevel, {num = num, activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local beforeExp = self.homeDojo.exp
        local afterExp = checkNumber(jsonData.exp)
        local addExp = afterExp - beforeExp
        self.homeDojo.exp = afterExp
        if self:IsMaxLevel() then
            self.homeDojo.dailyExpStatus = 2
        end
        if callback then
            callback(addExp)
        end
    end)
end

--- 请求购买pass卡
---@param callback any
function ActivityFashionPassComponent:RequestBuyPassCard(callback)
    -- if callback then
    --     callback()
    -- end
    -- do return end

    local product = self.homeDojo:GetPassCardProduct()
    if table.count(checkTable(product.prices)) > 0 then
        -- 消耗的货币和数量
        local currency, current
        for k, v in pairs(product.prices) do
            currency = checkInt(k)
            current = checkInt(v.current)
            break
        end

        local toBuyPassProduct = function()
            local requestData = {productId = product.productId, num = 1, currency = currency, activityUuid = self.activityUuid}
            GameUtils.Request(Interfaces.ActivityFashionPassSignInPassBuy, requestData, function(request, response)
                if checkInt(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    -- 消耗钻石
                    GoodsUtils.ConsumeGoods({{goodsId = currency, num = current, productId = checkNumber(product.productId)}}, true)
                    if callback then
                        callback()
                    end
                end
            end)
        end

        local _, errorTips = GoodsUtils.CheckGoodConsume(product.prices)
        if errorTips then
            if serverDifferenceMgr:IsSecondaryCurrencyEnable() then
                serverDifferenceMgr:WrapPrimaryCurrencyBuy({currency = currency, current = current}, nil, function(isSuccess)
                    if checkBool(isSuccess) then
                        toBuyPassProduct()
                    end
                end)
            else
                GameUtils.Toast(errorTips)
            end
            return
        end

        local consumeVo = GoodsConfMgr:GetInstance():GetGoodsVoById(currency)
        local text = localize("确认花费_Num__Name_购买商品?", {_Num_ = current, _Name_ = consumeVo.name})
        GameUtils.SecondConfirm(text, toBuyPassProduct, nil)

    else
        SDKService:GetInstance():PayMoney({
            productId        = product.productId,
            channelProductId = product.channelProductId,
            productDesc      = localize("商品"),
            payAmount        = product.price,
            data             = product
        })
    end
end

