--- 指定排期的全部基础奖励表
---@param scheduleId any
---@return FashionPassBaseRewardVo[]
function ActivityFashionPassComponent:GetBaseRewardVosByScheduleId(scheduleId)
    local cid = scheduleId
    local ids = CfUtils.GetIdGroupValue(AutoIds.IdSetting6716, cid, 'ids', 'IDGroup')
    local idList = parse_strings(ids, ',')
    local vos = {}
    for i, id in ipairs(idList) do
        local vo = self:GetBaseRewardVo(checkNumber(id))
        table.insert(vos, vo)
    end
    return vos
end

